1	package tariff
2	
3	import (
4		"errors"
5		"math"
6		"sort"
7		"sync"
8		"time"
9	)
10	
11	// 登记费率版本时可能返回的错误。
12	var (
13		ErrEmptyItemID            = errors.New("tariff: item id must not be empty")
14		ErrEmptyVersionID         = errors.New("tariff: version id must not be empty")
15		ErrInvalidUnitPrice       = errors.New("tariff: unit price must not be negative")
16		ErrStartRequired          = errors.New("tariff: effective start time is required")
17		ErrInvalidInterval        = errors.New("tariff: end time must be after start time")
18		ErrVersionExists          = errors.New("tariff: version id already registered for the item")
19		ErrOverlap                = errors.New("tariff: version interval overlaps an existing version of the item")
20		ErrReplaceTargetNotFound  = errors.New("tariff: replaced version does not exist")
21		ErrReplaceTargetWrongItem = errors.New("tariff: replaced version belongs to another item")
22		ErrInvalidReplacement     = errors.New("tariff: new version start must be after the replaced version start and within its current effective interval")
23	)
24	
25	// 查询与报价时可能返回的错误。
26	var (
27		ErrItemNotFound       = errors.New("tariff: rate item not found")
28		ErrNoEffectiveVersion = errors.New("tariff: no effective version for the rate item at the given time")
29		ErrRequestNotFound    = errors.New("tariff: request id not found")
30		ErrRequestIDConflict  = errors.New("tariff: request id already used with different content")
31	)
32	
33	// RejectReason 区分报价被拒绝的原因。
34	type RejectReason string
35	
36	const (
37		ReasonNone                   RejectReason = ""
38		ReasonEmptyRequestID         RejectReason = "empty_request_id"
39		ReasonInvalidQuantity        RejectReason = "invalid_quantity"
40		ReasonVersionNotFound        RejectReason = "version_not_found"
41		ReasonVersionNotYetEffective RejectReason = "version_not_yet_effective"
42		ReasonVersionExpired         RejectReason = "version_expired"
43		ReasonTotalOverflow          RejectReason = "total_overflow"
44	)
45	
46	// RegisterRequest 描述一次费率版本登记。
47	type RegisterRequest struct {
48		ItemID    string
49		VersionID string
50		UnitPrice int64      // 整数分单价，可以为零，不能为负
51		Start     time.Time  // 必填，生效时刻（含）
52		End       *time.Time // 可选，结束时刻（不含）；nil 表示持续有效
53		Replaces  string     // 可选，同项内被本版本替代的旧版本标识
54	}
55	
56	// VersionView 是查询费率项时返回的版本视图，
57	// 同时包含登记的起止时间、替代关系和实际有效区间。
58	type VersionView struct {
59		ItemID         string
60		VersionID      string
61		UnitPrice      int64
62		Start          time.Time  // 登记的生效时刻（含）
63		End            *time.Time // 登记的结束时刻（不含），nil 表示持续有效
64		Replaces       string     // 本版本登记时替代的旧版本，空表示无
65		SupersededBy   string     // 替代本版本的新版本，空表示未被替代
66		EffectiveStart time.Time  // 实际有效区间起点（含）
67		EffectiveEnd   *time.Time // 实际有效区间终点（不含），nil 表示持续有效
68	}
69	
70	// QuoteRequest 描述一次报价请求。
71	type QuoteRequest struct {
72		RequestID string // 非空请求标识，用于幂等与查询
73		ItemID    string
74		VersionID string
75		Quantity  int64 // 正整数
76	}
77	
78	// Outcome 是报价的首次受理结果：要么确认，要么带原因拒绝。
79	// 成功报价即为已确认记录，之后费率变化不会改写其中的金额和来源。
80	type Outcome struct {
81		Request    QuoteRequest // 原请求内容
82		AcceptedAt time.Time    // 首次受理时刻
83		Confirmed  bool
84		UnitPrice  int64        // 确认时的实际单价（分）
85		Total      int64        // 确认时的总价（分）
86		Reason     RejectReason // 被拒绝时的原因
87	}
88	
89	// version 是登记在册的费率版本。effEnd 因被替代而可能早于登记的 end。
90	type version struct {
91		itemID       string
92		versionID    string
93		unitPrice    int64
94		start        time.Time
95		end          *time.Time
96		replaces     string
97		supersededBy string
98		effEnd       *time.Time
99	}
100	
101	// availability 描述版本在某一瞬间的可用性，是查询与报价共用的唯一判断口径。
102	type availability int
103	
104	const (
105		availabilityEffective availability = iota // 处于实际有效区间内
106		availabilityNotYet                        // 尚未到达生效起点
107		availabilityExpired                       // 已过实际有效终点
108	)
109	
110	// availabilityAt 判断版本在 t 这一瞬间是否处于实际有效区间 [start, effEnd)。
111	// 开始时刻包含在内，结束时刻不包含；effEnd 为 nil 表示持续有效。
112	// 被替代的版本以截短后的实际结束时刻（effEnd）为准，不看登记时填写的 end。
113	// 时间按实际时刻比较，同一瞬间的不同时区表示结论一致。
114	// 查询（EffectiveVersionAt）与报价（Quote）都以此为唯一判断，
115	// 只是各自传入的瞬间不同：查询用调用方指定的时刻，报价用首次受理时刻。
116	func (v *version) availabilityAt(t time.Time) availability {
117		if t.Before(v.start) {
118			return availabilityNotYet
119		}
120		if v.effEnd != nil && !t.Before(*v.effEnd) {
121			return availabilityExpired
122		}
123		return availabilityEffective
124	}
125	
126	// Book 是费率版本与报价的本地账本，可并发使用。
127	type Book struct {
128		mu       sync.Mutex
129		now      func() time.Time
130		items    map[string]map[string]*version // itemID -> versionID -> version
131		requests map[string]Outcome             // requestID -> 首次受理结果
132	}
133	
134	// Option 定制 Book 的行为。
135	type Option func(*Book)
136	
137	// WithClock 指定受理时刻的来源，默认使用 time.Now。
138	func WithClock(now func() time.Time) Option {
139		return func(b *Book) {
140			if now != nil {
141				b.now = now
142			}
143		}
144	}
145	
146	// NewBook 返回一个空的账本。
147	func NewBook(opts ...Option) *Book {
148		b := &Book{
149			now:      time.Now,
150			items:    make(map[string]map[string]*version),
151			requests: make(map[string]Outcome),
152		}
153		for _, opt := range opts {
154			opt(b)
155		}
156		return b
157	}
158	
159	// RegisterVersion 登记一个费率版本。任何校验失败都不会留下部分变更。
160	func (b *Book) RegisterVersion(req RegisterRequest) error {
161		b.mu.Lock()
162		defer b.mu.Unlock()
163	
164		if req.ItemID == "" {
165			return ErrEmptyItemID
166		}
167		if req.VersionID == "" {
168			return ErrEmptyVersionID
169		}
170		if req.UnitPrice < 0 {
171			return ErrInvalidUnitPrice
172		}
173		if req.Start.IsZero() {
174			return ErrStartRequired
175		}
176		if req.End != nil && !req.End.After(req.Start) {
177			return ErrInvalidInterval
178		}
179	
180		versions := b.items[req.ItemID]
181		if _, ok := versions[req.VersionID]; ok {
182			return ErrVersionExists
183		}
184	
185		var target *version
186		if req.Replaces != "" {
187			t, ok := versions[req.Replaces]
188			if !ok {
189				if b.versionInOtherItem(req.ItemID, req.Replaces) {
190					return ErrReplaceTargetWrongItem
191				}
192				return ErrReplaceTargetNotFound
193			}
194			// 新版本的开始必须晚于旧版本的开始，且落在旧版本当前的有效区间内。
195			if !req.Start.After(t.start) {
196				return ErrInvalidReplacement
197			}
198			if t.effEnd != nil && !req.Start.Before(*t.effEnd) {
199				return ErrInvalidReplacement
200			}
201			target = t
202		}
203	
204		// 与同项其他版本的实际有效区间比较，不允许重叠；
205		// 被替代版本会被截断到新版本开始时刻，不参与重叠判断。
206		for _, v := range versions {
207			if v == target {
208				continue
209			}
210			if intervalsOverlap(req.Start, req.End, v.start, v.effEnd) {
211				return ErrOverlap
212			}
213		}
214	
215		// 全部校验通过后才提交变更。结束时刻必须复制后入库：
216		// 既不能与调用方的请求变量共享指针，登记结束与实际结束之间也互为独立副本，
217		// 外部对原变量或任一返回结果的修改都不能改写账本中的边界。
218		v := &version{
219			itemID:    req.ItemID,
220			versionID: req.VersionID,
221			unitPrice: req.UnitPrice,
222			start:     req.Start,
223			end:       cloneTimePtr(req.End),
224			replaces:  req.Replaces,
225			effEnd:    cloneTimePtr(req.End),
226		}
227		if target != nil {
228			truncated := req.Start
229			target.effEnd = &truncated
230			target.supersededBy = req.VersionID
231		}
232		if versions == nil {
233			versions = make(map[string]*version)
234			b.items[req.ItemID] = versions
235		}
236		versions[req.VersionID] = v
237		return nil
238	}
239	
240	func (b *Book) versionInOtherItem(itemID, versionID string) bool {
241		for id, versions := range b.items {
242			if id == itemID {
243				continue
244			}
245			if _, ok := versions[versionID]; ok {
246				return true
247			}
248		}
249		return false
250	}
251	
252	// cloneTimePtr 返回结束时刻的独立副本，nil 原样返回。
253	// time.Time 是值类型，但账本持有的是 *time.Time，必须复制指针指向的值，
254	// 否则调用方修改自己的时间变量就会改写账本。
255	func cloneTimePtr(t *time.Time) *time.Time {
256		if t == nil {
257			return nil
258		}
259		cp := *t
260		return &cp
261	}
262	
263	// intervalsOverlap 判断半开区间 [s1,e1) 与 [s2,e2) 是否重叠，nil 终点表示持续有效。
264	// 时间比较按实际时刻进行，不同时区偏移不影响结果。
265	func intervalsOverlap(s1 time.Time, e1 *time.Time, s2 time.Time, e2 *time.Time) bool {
266		if e1 != nil && !s2.Before(*e1) {
267			return false
268		}
269		if e2 != nil && !s1.Before(*e2) {
270			return false
271		}
272		return true
273	}
274	
275	// versionView 构造账本版本的独立视图。
276	// 结束时刻必须复制后返回：登记结束与实际结束各自生成独立副本，
277	// 不同次查询之间也不共享指针，外部对任一返回结果的修改都不能改写账本边界。
278	func versionView(v *version) VersionView {
279		return VersionView{
280			ItemID:         v.itemID,
281			VersionID:      v.versionID,
282			UnitPrice:      v.unitPrice,
283			Start:          v.start,
284			End:            cloneTimePtr(v.end),
285			Replaces:       v.replaces,
286			SupersededBy:   v.supersededBy,
287			EffectiveStart: v.start,
288			EffectiveEnd:   cloneTimePtr(v.effEnd),
289		}
290	}
291	
292	// ItemVersions 返回费率项下各版本的登记信息与实际有效区间，按生效时刻排序。
293	func (b *Book) ItemVersions(itemID string) ([]VersionView, error) {
294		b.mu.Lock()
295		defer b.mu.Unlock()
296	
297		versions, ok := b.items[itemID]
298		if !ok || len(versions) == 0 {
299			return nil, ErrItemNotFound
300		}
301		views := make([]VersionView, 0, len(versions))
302		for _, v := range versions {
303			views = append(views, versionView(v))
304		}
305		sort.Slice(views, func(i, j int) bool {
306			if !views[i].EffectiveStart.Equal(views[j].EffectiveStart) {
307				return views[i].EffectiveStart.Before(views[j].EffectiveStart)
308			}
309			return views[i].VersionID < views[j].VersionID
310		})
311		return views, nil
312	}
313	
314	// EffectiveVersionAt 返回指定费率项在 at 这一瞬间实际生效的单个版本。
315	//
316	// 选择依据是查询时账本已经登记的实际有效区间 [EffectiveStart, EffectiveEnd)：
317	// 开始时刻包含在内，结束时刻不包含在内，实际结束为 nil 表示持续有效。
318	// 旧版本被替代后，其实际有效区间止于交接时刻，从交接时刻起便不会再被选中，
319	// 即便它登记的结束时间仍在将来；替代它的新版本到期后也不会回退到旧版本。
320	// at 可以是过去或未来的任意瞬间，与账本时钟无关。
321	//
322	// 时间按实际时刻比较，同一瞬间的不同时区表示结论一致；
323	// 选择只在指定费率项内进行，其他费率项中同名的版本不参与。
324	//
325	// 费率项从未登记过版本时返回 ErrItemNotFound；费率项存在但该瞬间没有任何
326	// 生效版本（早于首版开始、落在两版之间的空档或全部已到期）时返回
327	// ErrNoEffectiveVersion，不会拿邻近版本补位。
328	//
329	// 该查询只读取版本信息，不受理报价、不占用请求标识，也不影响已保存的
330	// 受理结果。返回的 VersionView 是独立副本，修改其中的结束时间不会改变账本。
331	func (b *Book) EffectiveVersionAt(itemID string, at time.Time) (VersionView, error) {
332		b.mu.Lock()
333		defer b.mu.Unlock()
334	
335		versions, ok := b.items[itemID]
336		if !ok || len(versions) == 0 {
337			return VersionView{}, ErrItemNotFound
338		}
339		var found *version
340		for _, v := range versions {
341			if v.availabilityAt(at) != availabilityEffective {
342				continue
343			}
344			// 同一费率项内各版本的实际有效区间互不重叠，至多一版命中。
345			found = v
346			break
347		}
348		if found == nil {
349			return VersionView{}, ErrNoEffectiveVersion
350		}
351		return versionView(found), nil
352	}
353	
354	// Quote 按首次受理时刻判断指定版本是否有效并给出报价。
355	// 非空请求标识的首次结果（无论确认还是拒绝）都会被保存；
356	// 相同标识且业务内容相同的重试返回首次结果，内容不同则返回 ErrRequestIDConflict。
357	func (b *Book) Quote(req QuoteRequest) (Outcome, error) {
358		b.mu.Lock()
359		defer b.mu.Unlock()
360	
361		if req.RequestID == "" {
362			return Outcome{
363				Request:    req,
364				AcceptedAt: b.now(),
365				Reason:     ReasonEmptyRequestID,
366			}, nil
367		}
368	
369		if prev, ok := b.requests[req.RequestID]; ok {
370			same := prev.Request.ItemID == req.ItemID &&
371				prev.Request.VersionID == req.VersionID &&
372				prev.Request.Quantity == req.Quantity
373			if !same {
374				return Outcome{}, ErrRequestIDConflict
375			}
376			return prev, nil
377		}
378	
379		out := Outcome{Request: req, AcceptedAt: b.now()}
380		switch {
381		case req.Quantity <= 0:
382			out.Reason = ReasonInvalidQuantity
383		default:
384			v := b.items[req.ItemID][req.VersionID]
385			// 可用性以首次受理时刻为准，与查询共用同一套实际有效期判断；
386			// 只有版本有效后才判断总价是否溢出。
387			var avail availability
388			if v != nil {
389				avail = v.availabilityAt(out.AcceptedAt)
390			}
391			switch {
392			case v == nil:
393				out.Reason = ReasonVersionNotFound
394			case avail == availabilityNotYet:
395				out.Reason = ReasonVersionNotYetEffective
396			case avail == availabilityExpired:
397				out.Reason = ReasonVersionExpired
398			case v.unitPrice > 0 && req.Quantity > math.MaxInt64/v.unitPrice:
399				out.Reason = ReasonTotalOverflow
400			default:
401				out.Confirmed = true
402				out.UnitPrice = v.unitPrice
403				out.Total = v.unitPrice * req.Quantity
404			}
405		}
406		b.requests[req.RequestID] = out
407		return out, nil
408	}
409	
410	// Lookup 按请求标识查询保存的首次受理结果，未见过的标识返回 ErrRequestNotFound。
411	func (b *Book) Lookup(requestID string) (Outcome, error) {
412		b.mu.Lock()
413		defer b.mu.Unlock()
414	
415		out, ok := b.requests[requestID]
416		if !ok {
417			return Outcome{}, ErrRequestNotFound
418		}
419		return out, nil
420	}
421

