11	// 同一请求标识被多个调用方同时用于不同数量时的首次受理规则回归测试。
12	//
13	// 这些测试只通过公开的 Quote / Lookup 功能与既有错误语义施加负载，
14	// 不修改费率登记、金额计算或首次受理规则本身：
15	//
16	//   - 并发批次中两种数量各占一半，谁先抢到账本的受理权是调度决定的，
17	//     因此测试不断言某个固定数量必然先被受理，而是按实际首次内容校验；
18	//   - 与首次内容相同的请求全部原样返回同一份首次结果；
19	//   - 数量不同的请求全部返回 ErrRequestIDConflict，不产生各自的确认价，
20	//     也不把后到的数量写入查询记录。
21	//
22	// 为让结论可重复执行，批次运行在注入的固定时钟下；批次结束后再推进时钟，
23	// 验证延后重试不改写首次受理时刻。
24	
25	const (
26		raceItemID    = "seat"
27		raceVersionID = "v1"
28		raceUnitPrice = int64(7)
29		racePerSide   = 32 // 每种数量的并发调用数
30	)
31	
32	// raceCall 记录一次并发报价的实际返回及其数量。
33	type raceCall struct {
34		quantity int64
35		out      Outcome
36		err      error
37	}
38	
39	// newRaceBook 准备一本已生效的单价 7 分版本账本，版本自 at(0) 起持续有效，
40	// 受理时刻初始固定在 at(5)（版本有效期内）。返回账本和推进时钟的函数。
41	func newRaceBook(t *testing.T, start time.Time) (*Book, func(time.Time)) {
42		t.Helper()
43		now, setNow := fixedClock(start)
44		b := NewBook(WithClock(now))
45		if err := b.RegisterVersion(RegisterRequest{
46			ItemID: raceItemID, VersionID: raceVersionID,
47			UnitPrice: raceUnitPrice, Start: at(0),
48		}); err != nil {
49			t.Fatalf("register %s/%s: %v", raceItemID, raceVersionID, err)
50		}
51		return b, setNow
52	}
53	
54	// raceDifferentQuantities 同时提交 2*racePerSide 个相同标识、相同费率项与版本、
55	// 仅数量不同的报价（两种数量交替排列）。所有 goroutine 经同一屏障同时放行，
56	// 返回每一次调用拿到的真实结果。
57	func raceDifferentQuantities(b *Book, requestID string, qA, qB int64) []raceCall {
58		calls := make([]raceCall, 2*racePerSide)
59		start := make(chan struct{})
60		var wg sync.WaitGroup
61		for i := range calls {
62			q := qA
63			if i%2 == 1 {
64				q = qB
65			}
66			wg.Add(1)
67			go func(i int, q int64) {
68				defer wg.Done()
69				<-start // 全部就绪后一起进入 Quote，制造对同一标识的同时竞争
70				out, err := b.Quote(QuoteRequest{
71					RequestID: requestID,
72					ItemID:    raceItemID,
73					VersionID: raceVersionID,
74					Quantity:  q,
75				})
76				calls[i] = raceCall{quantity: q, out: out, err: err}
77			}(i, q)
78		}
79		close(start)
80		wg.Wait()
81		return calls
82	}
83	
84	// checkFirstAcceptanceRace 校验并发批次的结果符合首次受理规则，
85	// 返回保存的首次结果及其数量。不断言哪种数量先被受理。
86	func checkFirstAcceptanceRace(t *testing.T, requestID string, qA, qB int64, calls []raceCall) (Outcome, int64) {
87		t.Helper()
88	
89		var accepted, conflicts []raceCall
90		for _, c := range calls {
91			if c.err == nil {
92				accepted = append(accepted, c)
93			} else {
94				conflicts = append(conflicts, c)
95			}
96		}
97	
98		// 恰好一半调用（与首次内容相同的那一半）正常受理，另一半全部冲突；
99		// 不能两种数量各自产生确认价。
100		if want, got := racePerSide, len(accepted); want != got {
101			t.Fatalf("正常受理次数=%d，应恰好为 %d（同内容的一半）；冲突 %d 次",
102				got, want, len(conflicts))
103		}
104		if want, got := racePerSide, len(conflicts); want != got {
105			t.Fatalf("冲突次数=%d，应恰好为 %d（不同数量的一半）；正常受理 %d 次",
106				got, want, len(accepted))
107		}
108	
109		first := accepted[0].out
110		winQ := first.Request.Quantity
111		if winQ != qA && winQ != qB {
112			t.Fatalf("首次结果数量=%d，应为两种竞争数量 %d/%d 之一", winQ, qA, qB)
113		}
114		loseQ := qA
115		if winQ == qA {
116			loseQ = qB
117		}
118	
119		// 与首次内容相同的调用都必须取回完全一致的首次结果（含首次受理时刻），
120		// 数量不同的调用都只能拿到 ErrRequestIDConflict 和零值结果，
121		// 不能借冲突路径返回任何可用报价。
122		for _, c := range accepted {
123			if c.quantity != winQ {
124				t.Fatalf("数量 %d 的请求也取得了受理结果，首次数量是 %d：%+v",
125					c.quantity, winQ, c.out)
126			}
127			if c.out != first {
128				t.Fatalf("同内容并发调用结果不一致：%+v vs %+v", first, c.out)
129			}
130		}
131		for _, c := range conflicts {
132			if !errors.Is(c.err, ErrRequestIDConflict) {
133				t.Fatalf("数量 %d 应返回 ErrRequestIDConflict，got %v", c.quantity, c.err)
134			}
135			if c.quantity != loseQ {
136				t.Fatalf("与首次同数量(%d)的请求不应冲突", winQ)
137			}
138			if c.out != (Outcome{}) {
139				t.Fatalf("冲突调用不得携带可用结果：%+v", c.out)
140			}
141		}
142	
143		// 首次结果必须原样保留费率项、版本、标识和数量。
144		wantReq := QuoteRequest{RequestID: requestID, ItemID: raceItemID, VersionID: raceVersionID, Quantity: winQ}
145		if first.Request != wantReq {
146			t.Fatalf("首次结果请求来源=%+v，want %+v", first.Request, wantReq)
147		}
148		if first.AcceptedAt.IsZero() {
149			t.Fatal("首次结果缺少受理时刻")
150		}
151		return first, winQ
152	}
153	
154	// checkStoredFirstResult 校验批次结束后 Lookup 与原样重试取回的是同一份保存结果，
155	// 换另一数量仍冲突，且延后提交不会改写首次受理时刻。
156	func checkStoredFirstResult(t *testing.T, b *Book, requestID string, first Outcome, winQ, loseQ int64) {
157		t.Helper()
158		winReq := QuoteRequest{RequestID: requestID, ItemID: raceItemID, VersionID: raceVersionID, Quantity: winQ}
159		loseReq := winReq
160		loseReq.Quantity = loseQ
161	
162		got, err := b.Lookup(requestID)
163		if err != nil {
164			t.Fatalf("按标识查询首次结果: %v", err)
165		}
166		if got != first {
167			t.Fatalf("查询未取回保存的首次结果: %+v vs %+v", first, got)
168		}
169	
170		// 原样再次提交首次内容：返回完全一致的首次结果，受理时刻不变。
171		replay, err := b.Quote(winReq)
172		if err != nil {
173			t.Fatalf("原样重试首次内容: %v", err)
174		}
175		if replay != first {
176			t.Fatalf("原样重试改写了首次结果: %+v vs %+v", first, replay)
177		}
178		if !replay.AcceptedAt.Equal(first.AcceptedAt) {
179			t.Fatalf("延后重试改写了受理时刻: %v vs %v", replay.AcceptedAt, first.AcceptedAt)
180		}
181	
182		// 换用另一数量仍是标识冲突，保存记录不变。
183		if _, err := b.Quote(loseReq); !errors.Is(err, ErrRequestIDConflict) {
184			t.Fatalf("换数量提交应返回 ErrRequestIDConflict, got %v", err)
185		}
186		again, err := b.Lookup(requestID)
187		if err != nil {
188			t.Fatalf("冲突后查询: %v", err)
189		}
190		if again != first {
191			t.Fatalf("冲突请求改写了保存记录: %+v vs %+v", first, again)
192		}
193	}
194	
195	// TestConcurrentConfirmedQuantitiesFirstWins：单价 7 分的有效版本下，
196	// 同一非空标识同时用于数量 2 和数量 5。
197	//
198	// 数量 2 先受理则保存并返回 14 分确认；数量 5 先受理则保存并返回 35 分确认，
199	// 单价都为 7 分。测试允许任意一种先被受理，两种路径都做完整校验。
200	// 多轮独立账本重复执行，提高两种调度顺序在多次运行中都被覆盖的机会，
201	// 但不要求同一轮内固定某一方获胜。
202	func TestConcurrentConfirmedQuantitiesFirstWins(t *testing.T) {
203		const rounds = 8
204		winners := map[int64]int{}
205		for round := 0; round < rounds; round++ {
206			t.Run(fmt.Sprintf("round-%d", round), func(t *testing.T) {
