1	package tariff
2	
3	import (
4		"errors"
5		"math"
6		"sync"
7		"testing"
8		"time"
9	)
10	
11	var base = time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC)
12	
13	func at(hours int) time.Time { return base.Add(time.Duration(hours) * time.Hour) }
14	
15	func atPtr(hours int) *time.Time {
16		t := at(hours)
17		return &t
18	}
19	
20	// fixedClock 返回可手动推进的时钟。
21	func fixedClock(start time.Time) (func() time.Time, func(time.Time)) {
22		var mu sync.Mutex
23		cur := start
24		return func() time.Time {
25				mu.Lock()
26				defer mu.Unlock()
27				return cur
28			}, func(t time.Time) {
29				mu.Lock()
30				defer mu.Unlock()
31				cur = t
32			}
33	}
34	
35	func TestRegisterValidation(t *testing.T) {
36		b := NewBook()
